\set ON_ERROR_STOP on
begin;
\ir 00-batch-inputs.sql
do $verify$ begin
  if (select count(*) from pg_trigger where tgrelid='public.nba_player_game_observation_versions'::regclass and not tgisinternal)<>2 or not exists(select 1 from pg_trigger where tgrelid='public.nba_player_game_observation_versions'::regclass and tgname='nba_observation_versions_sync_current' and tgenabled='O' and tgtype=5 and tgfoid='public.sync_nba_current_observation()'::regprocedure) or not exists(select 1 from pg_trigger where tgrelid='public.nba_player_game_observation_versions'::regclass and tgname='nba_observation_versions_immutable' and tgenabled='O' and tgtype=27 and tgfoid='public.reject_nba_projection_observation_version_mutation()'::regprocedure) then raise exception 'Unexpected NBA observation triggers'; end if;
  if (select btrim(regexp_replace(prosrc,'[[:space:]]+',' ','g')) from pg_proc where oid='public.sync_nba_current_observation()'::regprocedure) is distinct from 'begin insert into public.nba_player_game_current_observations ( provider, provider_player_id, provider_event_id, version_id, local_player_id, season, phase, game_at, completed_at, team_provider_id, team_abbreviation, opponent_provider_id, opponent_abbreviation, home_away, minutes, points, rebounds, assists, steals, blocks, turnovers, source_url, provider_fetched_at, provider_known_at, normalization_version, observation_hash, created_at ) values ( new.provider, new.provider_player_id, new.provider_event_id, new.id, new.local_player_id, new.season, new.phase, new.game_at, new.completed_at, new.team_provider_id, new.team_abbreviation, new.opponent_provider_id, new.opponent_abbreviation, new.home_away, new.minutes, new.points, new.rebounds, new.assists, new.steals, new.blocks, new.turnovers, new.source_url, new.provider_fetched_at, new.provider_known_at, new.normalization_version, new.observation_hash, new.created_at ) on conflict (provider, provider_player_id, provider_event_id) do update set version_id = excluded.version_id, local_player_id = excluded.local_player_id, season = excluded.season, phase = excluded.phase, game_at = excluded.game_at, completed_at = excluded.completed_at, team_provider_id = excluded.team_provider_id, team_abbreviation = excluded.team_abbreviation, opponent_provider_id = excluded.opponent_provider_id, opponent_abbreviation = excluded.opponent_abbreviation, home_away = excluded.home_away, minutes = excluded.minutes, points = excluded.points, rebounds = excluded.rebounds, assists = excluded.assists, steals = excluded.steals, blocks = excluded.blocks, turnovers = excluded.turnovers, source_url = excluded.source_url, provider_fetched_at = excluded.provider_fetched_at, provider_known_at = excluded.provider_known_at, normalization_version = excluded.normalization_version, observation_hash = excluded.observation_hash, created_at = excluded.created_at where excluded.provider_fetched_at > nba_player_game_current_observations.provider_fetched_at or ( excluded.provider_fetched_at = nba_player_game_current_observations.provider_fetched_at and excluded.version_id > nba_player_game_current_observations.version_id ); return new; end;' then raise exception 'Unexpected function body: sync_nba_current_observation'; end if;
  if (select btrim(regexp_replace(prosrc,'[[:space:]]+',' ','g')) from pg_proc where oid='public.reject_nba_projection_observation_version_mutation()'::regprocedure) is distinct from 'begin raise exception ''NBA player-game observation versions are immutable''; end;' then raise exception 'Unexpected function body: reject_nba_projection_observation_version_mutation'; end if;
  if exists(select 1 from pg_trigger where tgrelid='public.player_center_season_cache'::regclass and not tgisinternal) then raise exception 'Unexpected cache trigger'; end if;
  if (select count(*) from _pc_cache) not between 1 and 25 or (select count(*) from _pc_obs)>1000 or (select count(distinct as_of) from _pc_cache)<>1 then raise exception 'Invalid batch size/cutoff'; end if;
  if exists(select 1 from _pc_cache where sport<>'nba' or season<>2027 or phase<>'regular') or exists(select 1 from _pc_obs where season<>2027 or phase<>'regular' or local_player_id is null or game_at<'2026-09-01T00:00:00Z'::timestamptz or game_at>='2027-09-01T00:00:00Z'::timestamptz or game_at>provider_fetched_at) then raise exception 'Invalid season/identity boundary'; end if;
  if exists(select 1 from _pc_native n left join public.players p on p.id=n.local_id where p.nba_player_id is distinct from n.native_id or p.is_active is distinct from true) then raise exception 'Native catalog changed'; end if;
  if exists(select 1 from _pc_cache s left join public.nba_player_provider_identities i on i.provider=s.provider and i.provider_player_id=s.provider_player_id where i.resolution_status is distinct from 'resolved' or i.player_id is distinct from s.nba_local_player_id) then raise exception 'Reviewed mappings must be applied first'; end if;
  if exists(select 1 from _pc_obs s left join _pc_cache c on c.provider_player_id=s.provider_player_id and c.nba_local_player_id=s.local_player_id where c.provider_player_id is null) then raise exception 'Observation outside reviewed batch'; end if;
  if exists(select 1 from public.nba_player_game_current_observations c join _pc_obs s on c.provider=s.provider and c.provider_player_id=s.provider_player_id and c.provider_event_id=s.provider_event_id where c.local_player_id is distinct from s.local_player_id or c.season<>2027 or (c.provider_fetched_at>s.provider_fetched_at and row(c.local_player_id,c.season,c.phase,c.game_at,c.completed_at,c.team_provider_id,c.team_abbreviation,c.opponent_provider_id,c.opponent_abbreviation,c.home_away,c.minutes,c.points,c.rebounds,c.assists,c.steals,c.blocks,c.turnovers,c.normalization_version) is distinct from row(s.local_player_id,s.season,s.phase,s.game_at,s.completed_at,s.team_provider_id,s.team_abbreviation,s.opponent_provider_id,s.opponent_abbreviation,s.home_away,s.minutes,s.points,s.rebounds,s.assists,s.steals,s.blocks,s.turnovers,s.normalization_version))) then raise exception 'Newer/conflicting current evidence exists'; end if;

  if exists(select 1 from _pc_cache s left join public.player_center_season_cache a on a.sport=s.sport and a.provider=s.provider and a.provider_player_id=s.provider_player_id and a.season=s.season and a.phase=s.phase where to_jsonb(a) is distinct from to_jsonb(s)) then raise exception 'Published cache changed or absent'; end if;
end $verify$;
\copy (select c.* from public.player_center_season_cache c join _pc_cache s on c.sport=s.sport and c.provider=s.provider and c.provider_player_id=s.provider_player_id and c.season=s.season and c.phase=s.phase order by c.provider_player_id) to 'season-cache-after.csv' with(format csv,header true)
select provider_player_id,expected_games,observed_games,complete,checked_at,issues from _pc_cache order by provider_player_id;
commit;
